\input{result}

\end{document}

\section{Results}
\subsection{Psychomotor Vigilance}
Performance on the psychomotor vigilance task declined after the
second restricted night. Table~\ref{tab:pvt} reports the primary
outcomes for the per-protocol sample.

\begin{table}[h]
\centering
\begin{tabular}{lcc}
\toprule
Measure & Mean & SD \\
\midrule
Simple reaction time (ms) & 348 & 12 \\
Lapses (count) & 4.6 & 1.3 \\
False starts (count) & 0.8 & 0.4 \\
\bottomrule
\end{tabular}
\caption{Psychomotor vigilance outcomes, per-protocol sample.}
\label{tab:pvt}
\end{table}

\subsection{Subjective Sleepiness}
Self-reported sleepiness rose monotonically across the protocol
and tracked the objective vigilance decline.

